full/powershell/opencode/ollama-embed/ol.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and Ollama for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "openai",
    "model": "qwen3-coder:30b",
    "base_url": "http://localhost:11434/v1"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8

# Configure OpenCode to connect to ChunkHound via MCP.
if (Test-Path 'opencode.json') {
Write-Host @'
opencode.json already exists — merge this block into it manually:
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
'@
} else {
@'
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
'@ | Set-Content -Path 'opencode.json' -Encoding utf8
}

